import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:pdf_engine_core/pdf_engine_core.dart';
import 'package:test/test.dart';

/// Shared corpus generated by tool/generate_fixtures.py.
const _fixtureDir = '../fixtures/pdf';

Object? _field(PdfPreflightReport report, String name) => switch (name) {
  'isPdf' => report.isPdf,
  'version' => report.version,
  'isEncrypted' => report.isEncrypted,
  'usesObjectStreams' => report.usesObjectStreams,
  'usesCrossReferenceStreams' => report.usesCrossReferenceStreams,
  'hasClassicTrailer' => report.hasClassicTrailer,
  'hasAcroForm' => report.hasAcroForm,
  'hasXfa' => report.hasXfa,
  'revisionCount' => report.revisionCount,
  'isReadable' => report.isReadable,
  'isIncrementallyWritable' => report.isIncrementallyWritable,
  _ => throw ArgumentError('Unknown manifest expectation: $name'),
};

Uint8List _ascii(String text) => Uint8List.fromList(ascii.encode(text));

void main() {
  group('fixture corpus', () {
    final manifest =
        jsonDecode(File('$_fixtureDir/manifest.json').readAsStringSync())
            as Map<String, Object?>;
    final fixtures = (manifest['fixtures']! as List<Object?>)
        .cast<Map<String, Object?>>();

    test('has at least 20 fixtures', () {
      expect(fixtures.length, greaterThanOrEqualTo(20));
    });

    for (final fixture in fixtures) {
      final file = fixture['file']! as String;
      test('preflight matches manifest for $file', () {
        final report = PdfPreflight.inspect(
          File('$_fixtureDir/$file').readAsBytesSync(),
        );
        final expectations = (fixture['expect']! as Map<String, Object?>);
        for (final entry in expectations.entries) {
          if (entry.value == null) {
            continue;
          }
          expect(_field(report, entry.key), entry.value, reason: entry.key);
        }
      });
    }
  });

  group('PdfPreflight.inspect', () {
    test('reads the header version', () {
      final report = PdfPreflight.inspect(_ascii('%PDF-1.7\n%%EOF\n'));
      expect(report.isPdf, isTrue);
      expect(report.version, '1.7');
      expect(report.revisionCount, 1);
    });

    test('rejects a header found after the first 1024 bytes', () {
      final report = PdfPreflight.inspect(
        _ascii('${'x' * 1100}%PDF-1.4\n'),
      );
      expect(report.isPdf, isFalse);
      expect(report.version, isNull);
    });

    test('does not treat /XRefStm as a cross-reference stream', () {
      final report = PdfPreflight.inspect(
        _ascii('%PDF-1.5\ntrailer\n<< /Size 3 /XRefStm 120 >>\n%%EOF\n'),
      );
      expect(report.usesCrossReferenceStreams, isFalse);
      expect(report.hasClassicTrailer, isTrue);
    });

    test('ignores the word Encrypt when it is not a dictionary entry', () {
      final report = PdfPreflight.inspect(
        _ascii('%PDF-1.4\n(/Encrypt is just text) Tj\ntrailer\n<< >>\n'),
      );
      expect(report.isEncrypted, isFalse);
    });

    test('detects an inline /Encrypt dictionary', () {
      final report = PdfPreflight.inspect(
        _ascii('%PDF-1.4\ntrailer\n<< /Encrypt << /Filter /Standard >> >>\n'),
      );
      expect(report.isEncrypted, isTrue);
    });
  });

  group('PdfPreflightReport guards', () {
    PdfPreflightReport report({
      bool isPdf = true,
      bool isEncrypted = false,
      bool usesObjectStreams = false,
      bool usesCrossReferenceStreams = false,
      bool hasClassicTrailer = true,
    }) => PdfPreflightReport(
      isPdf: isPdf,
      version: '1.4',
      isEncrypted: isEncrypted,
      usesObjectStreams: usesObjectStreams,
      usesCrossReferenceStreams: usesCrossReferenceStreams,
      hasClassicTrailer: hasClassicTrailer,
      hasAcroForm: true,
      hasXfa: false,
      revisionCount: 1,
    );

    Matcher unsupported(PdfUnsupportedFeature feature) => throwsA(
      isA<PdfUnsupportedFeatureException>().having(
        (error) => error.feature,
        'feature',
        feature,
      ),
    );

    test('a classic file passes both guards', () {
      final classic = report();
      classic.ensureReadable(operation: 'Test');
      classic.ensureIncrementallyWritable(operation: 'Test');
    });

    test('not a PDF throws PdfInvalidDocumentException', () {
      expect(
        () => report(isPdf: false).ensureReadable(operation: 'Test'),
        throwsA(isA<PdfInvalidDocumentException>()),
      );
    });

    test('encryption is reported before other problems', () {
      expect(
        () => report(
          isEncrypted: true,
          usesObjectStreams: true,
        ).ensureReadable(operation: 'Test'),
        unsupported(PdfUnsupportedFeature.encryption),
      );
    });

    test('object streams are unreadable', () {
      expect(
        () => report(usesObjectStreams: true).ensureReadable(operation: 'Test'),
        unsupported(PdfUnsupportedFeature.compressedObjectStreams),
      );
    });

    test('xref streams are readable but not incrementally writable', () {
      final hybrid = report(usesCrossReferenceStreams: true);
      hybrid.ensureReadable(operation: 'Test');
      expect(
        () => hybrid.ensureIncrementallyWritable(operation: 'Test'),
        unsupported(PdfUnsupportedFeature.crossReferenceStreams),
      );
    });

    test('a missing trailer is not incrementally writable', () {
      expect(
        () => report(
          hasClassicTrailer: false,
        ).ensureIncrementallyWritable(operation: 'Test'),
        throwsA(isA<PdfInvalidDocumentException>()),
      );
    });

    test('messages name the operation and the feature', () {
      final error = PdfUnsupportedFeatureException(
        PdfUnsupportedFeature.compressedObjectStreams,
        operation: 'Form parsing',
      );
      expect(
        error.message,
        'Form parsing does not support compressed object streams '
        '(PDF 1.5+) yet.',
      );
      expect(error, isA<PdfException>());
    });
  });
}
